// Normalize input from any source
const isWebhook = !!$node['Webhook Trigger'];
const isTelegram = !!$node['Telegram Trigger'];
const isEmail = !!$node['Email Trigger'];

let userInput = '';
let source = 'unknown';
let replyTo = '';

if (isWebhook) {
  const data = $node['Webhook Trigger'].json.body || $node['Webhook Trigger'].json;
  userInput = data.question || data.message || data.text || '';
  source = 'webhook';
  replyTo = data.chat_id || data.user_id || '';
} else if (isTelegram) {
  const data = $node['Telegram Trigger'].json;
  userInput = data.message?.text || data.text || '';
  source = 'telegram';
  replyTo = data.message?.chat?.id || data.chat?.id || '';
} else if (isEmail) {
  const data = $node['Email Trigger'].json;
  userInput = data.textPlain || data.body || data.subject || '';
  source = 'email';
  replyTo = data.from?.address || data.from || '';
}

// Detect language (simple heuristic)
const spanishWords = ['hola', 'gracias', 'precio', 'horario', 'cuanto', 'cuando', 'como', 'quiero', 'necesito'];
const isSpanish = spanishWords.some(w => userInput.toLowerCase().includes(w));

return [{
  json: {
    userInput: userInput.trim(),
    source: source,
    replyTo: replyTo,
    language: isSpanish ? 'es' : 'en',
    timestamp: new Date().toISOString()
  }
}];

// Check if we have a cached response
const cacheResult = $node['Check Redis Cache'].json;

if (cacheResult && cacheResult.value) {
  // Return cached response
  const cached = JSON.parse(cacheResult.value);
  return [{ json: { ...cached, fromCache: true } }];
}

// No cache - continue with AI processing
return [{ json: { continue: true, userInput: $('Normalize Input').first().json.userInput, language: $('Normalize Input').first().json.language } }];

// Extract relevant RAG context based on the question
const question = $('Normalize Input').first().json.userInput.toLowerCase();
const ragContent = $node['Read RAG Context'].json.data.toString();

// Keywords to section mapping
const sections = {
  'schedule': ragContent.match(/#{1,3}\s*SCHEDULES?[\s\S]*?(?=#{1,3}\s*[A-Z]|$)/gi)?.[0] || '',
  'price': ragContent.match(/#{1,3}\s*PRICE[\s\S]*?(?=#{1,3}\s*[A-Z]|$)/gi)?.[0] || '',
  'level': ragContent.match(/#{1,3}\s*(LANGUAGE\s*)?LEVELS?[\s\S]*?(?=#{1,3}\s*[A-Z]|$)/gi)?.[0] || '',
  'inscription': ragContent.match(/#{1,3}\s*INSCRIPTION[\s\S]*?(?=#{1,3}\s*[A-Z]|$)/gi)?.[0] || '',
  'certification': ragContent.match(/#{1,3}\s*CERTIFICATION[\s\S]*?(?=#{1,3}\s*[A-Z]|$)/gi)?.[0] || '',
  'modality': ragContent.match(/#{1,3}\s*MODALIT[\s\S]*?(?=#{1,3}\s*[A-Z]|$)/gi)?.[0] || ''
};

// Find relevant sections based on keywords in question
const keywords = {
  'schedule': ['horario', 'schedule', 'clase', 'hora', 'manana', 'tarde', 'noche', 'dia', 'lunes', 'martes'],
  'price': ['precio', 'price', 'costo', 'cuanto', 'pago', 'mensual', 'cuota', 'dolares', 'pesos'],
  'level': ['nivel', 'level', 'basico', 'intermedio', 'avanzado', 'principiante', 'beginner'],
  'inscription': ['inscripcion', 'enrollment', 'registro', 'matricular', 'registrar', 'inscribirse'],
  'certification': ['certificado', 'certification', 'certificado', 'examen', 'exams', 'diploma'],
  'modality': ['modalidad', 'modality', 'presencial', 'online', 'virtual', 'hibrido', 'hybrid', 'self-paced', 'autodidacta']
};

let relevantContext = '';
for (const [section, words] of Object.entries(keywords)) {
  if (words.some(w => question.includes(w))) {
    relevantContext += sections[section] + '\n\n';
  }
}

// If no specific section found, return intro and general info
if (!relevantContext) {
  relevantContext = ragContent.substring(0, 2000);
}

const language = $('Normalize Input').first().json.language;
const systemPrompt = language === 'es'
  ? 'Eres un asistente útil de una Academia de Idiomas en Colombia. SOLO responde preguntas basándote en el contexto proporcionado. Si la respuesta no está en el contexto, responde EXACTAMENTE con: [HANDOFF_REQUIRED]'
  : 'You are a helpful assistant for a Foreign Languages Academy in Colombia. ONLY answer questions based on the provided context. If the answer is not in the context, respond EXACTLY with: [HANDOFF_REQUIRED]';

return [{
  json: {
    relevantContext: relevantContext || ragContent.substring(0, 2000),
    question: question,
    language: language,
    systemPrompt: systemPrompt
  }
}];

// Parse Gemini response
const response = $input.first().json;
const normalizeData = $('Normalize Input').first().json;

let answer = '';

if (response.data?.candidates?.[0]?.content?.parts?.[0]?.text) {
  answer = response.data.candidates[0].content.parts[0].text;
} else if (response.error) {
  answer = normalizeData.language === 'es'
    ? 'Lo siento, hubo un error al procesar tu pregunta. Por favor, intenta más tarde.'
    : 'Sorry, there was an error processing your question. Please try again later.';
}

const needsHandoff = answer.includes('[HANDOFF_REQUIRED]');

if (needsHandoff) {
  answer = normalizeData.language === 'es'
    ? 'Lo siento, no tengo esa información en mi base de conocimientos. Por favor, contacta a la academia directamente para obtener más ayuda.'
    : 'I\'m sorry, I don\'t have that information in my knowledge base. Please contact the academy directly for more help.';
}

const result = {
  answer: answer,
  needsHandoff: needsHandoff,
  source: normalizeData.source,
  replyTo: normalizeData.replyTo,
  language: normalizeData.language,
  originalQuestion: normalizeData.userInput
};

// Save to cache (only successful, non-handoff responses)
if (!needsHandoff && answer) {
  $node['Save to Cache'].json = { ...result, cacheKey: 'cache:question:' + normalizeData.userInput.toLowerCase().trim() };
}

return [{
  json: result
}];
